// Quantitative backbone check for god-religions-truth
const z = { 'a.05': 1.959963985, 'a.01': 2.575829304, 'a.005': 2.807033768, 'p.80': 0.841621233 };
const lines = [];
const push = (k, v) => lines.push(k + ' -> ' + JSON.stringify(v));

// 1) Parity: per-event likelihood ratio exactly 1
const N = 1e6, BFp = Math.pow(1, N);
push('parity: BF over N=1e6 events with LR=1 each', BFp);
push('log10 BF', Math.log10(BFp));

// 2) Events needed to move prior odds: factor = targetOdds/priorOdds
const need = (r, priorOdds, targetOdds) => Math.ceil(Math.log(targetOdds / priorOdds) / Math.log(r));
const rows2 = [1.001, 1.005, 1.01, 1.05, 1.10, 1.20, 2, 5, 10].map(r => ({
  LR: r,
  'prior 1:1 -> posterior 20:1': need(r, 1, 20),
  'prior 100:1 against -> posterior 20:1 for': need(r, 1 / 100, 20)
}));
push('events needed', rows2);

// 3) Deity-specificity: two-arm 20% vs 5% (pooled two-proportion z test)
function nArm(p1, p2, za, zb) { const pb = (p1 + p2) / 2; return 2 * ((za + zb) ** 2) * pb * (1 - pb) / ((p1 - p2) ** 2); }
const p1 = 0.20, p2 = 0.05;
push('n/arm alpha=0.05, power=0.80', nArm(p1, p2, z['a.05'], z['p.80']));
push('n/arm alpha=0.01 (5-arm Bonferroni), power=0.80', nArm(p1, p2, z['a.01'], z['p.80']));
push('n/arm alpha=0.005 (10-arm), power=0.80', nArm(p1, p2, z['a.005'], z['p.80']));

// 4) Three day-exact predictions, LR=366 each
const bf3 = 366 ** 3;
push('BF for 3 day-exact predictions (366^3)', bf3);
push('log10 BF', Math.log10(bf3));

nodeRepl.write(lines.join('\n'));

